import json
import re
from html import unescape
from pathlib import Path

sources = json.loads(Path('source.json').read_text())


def base(index):
    return {key: sources[index][key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}


def impact(classification, assessment, limitations, burdens, effects=None):
    return {
        'version': 1,
        'classification': classification,
        'assessment': assessment,
        'scope_limitations': limitations,
        'new_burdens_review': burdens,
        'effects': effects or [],
    }


def effect(kind, measure, description, before, after, unit, population, transition, replacement, source_quote, proposed_quote):
    return dict(kind=kind, measure_id=measure, description=description,
                before=before, after=after, unit=unit,
                affected_population=population, conditions_and_transition=transition,
                replacement_or_new_burdens=replacement,
                source_quote=source_quote, proposed_quote=proposed_quote)


